            // (decision + result production) completes.  enable.auto.commit is
            // false, so this is the only place offsets advance.
            const RdKafka::ErrorCode commit_rc = consumer->commitSync(msg.get());
            if (commit_rc != RdKafka::ERR_NO_ERROR) {
                std::cerr << "manual commit failed: " << RdKafka::err2str(commit_rc) << '\n';
            }
        }

        consumer->close();
        producer->flush(5000);
        RdKafka::wait_destroyed(5000);
    } catch (const std::exception& e) {
        std::cerr << "risk_engine fatal: " << e.what() << '\n';
        return 1;
    }
    return 0;
}
