    // service because payload is an RAII std::string that will be destroyed at
    // the end of the loop iteration.  The zero-copy principle is still applied
    // on the inbound path with string_view parsing; outbound uses explicit copy
    // to avoid dangling memory and pointer lifetime bugs.
    const RdKafka::ErrorCode rc = producer.produce(
        topic,                              // 1. Topic name (std::string)
        RdKafka::Topic::PARTITION_UA,       // 2. Unassigned partition
        RdKafka::Producer::RK_MSG_COPY,     // 3. Message flags (copy payload)
        const_cast<char*>(payload.data()),  // 4. Payload pointer
        payload.size(),                     // 5. Payload size
        key.data(),                         // 6. Key bytes pointer
        key.size(),                         // 7. Key byte length
        0,                                  // 8. Timestamp (0 uses current time)
        nullptr                             // 9. Opaque message context pointer
